// Secure secrets management
// Use environment variables or cloud secrets manager in production

class SecretsManager {
  constructor() {
    this.secrets = new Map();
    this.initialized = false;
  }

  // Initialize secrets - should be called once at app startup
  async initialize() {
    if (this.initialized) {
      return;
    }

    const isProduction = process.env.NODE_ENV === 'production';

    if (isProduction) {
      // Production: Use cloud secrets manager or environment variables
      await this.loadFromEnvironment();
    } else {
      // Development: Use environment variables with fallback to secure local file
      await this.loadFromEnvironment();

      // For development, you could load from a secure location
      // but environment variables are preferred
    }

    this.validateSecrets();
    this.initialized = true;
  }

  async loadFromEnvironment() {
    // Load from process environment (recommended for all environments)
    const requiredSecrets = [
      'SESSION_SECRET',
      'JWT_SECRET',
      'DATABASE_URL'
    ];

    const optionalSecrets = [
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY',
      'STRIPE_SECRET_KEY',
      'API_KEYS'
    ];

    // Load required secrets
    for (const key of requiredSecrets) {
      const value = process.env[key];
      if (!value && process.env.NODE_ENV === 'production') {
        throw new Error(`Missing required secret: ${key}`);
      }
      this.secrets.set(key, value);
    }

    // Load optional secrets
    for (const key of optionalSecrets) {
      const value = process.env[key];
      if (value) {
        this.secrets.set(key, value);
      }
    }
  }

  validateSecrets() {
    // Validate secret formats and strengths
    const sessionSecret = this.secrets.get('SESSION_SECRET');
    if (sessionSecret && sessionSecret.length < 32) {
      console.warn('WARNING: SESSION_SECRET is too short (min 32 characters)');
    }

    const jwtSecret = this.secrets.get('JWT_SECRET');
    if (jwtSecret && jwtSecret.length < 32) {
      console.warn('WARNING: JWT_SECRET is too short (min 32 characters)');
    }
  }

  get(key) {
    if (!this.initialized) {
      throw new Error('SecretsManager not initialized. Call initialize() first.');
    }

    const value = this.secrets.get(key);
    if (!value && process.env.NODE_ENV === 'production') {
      throw new Error(`Secret not found: ${key}`);
    }

    return value;
  }

  // For testing purposes only
  set(key, value) {
    this.secrets.set(key, value);
  }
}

// Singleton instance
const secretsManager = new SecretsManager();

module.exports = secretsManager;

// Main application configuration
const secretsManager = require('./secrets');

const config = {
  // App settings
  env: process.env.NODE_ENV || 'development',
  port: process.env.PORT || 3000,

  // Security settings
  security: {
    sessionSecret: () => secretsManager.get('SESSION_SECRET'),
    jwtSecret: () => secretsManager.get('JWT_SECRET'),

    // Rate limiting
    rateLimit: {
      windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS) || 15 * 60 * 1000,
      max: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS) || 100
    },

    // Request limits
    requestSizeLimit: process.env.REQUEST_SIZE_LIMIT || '10kb'
  },

  // Database
  database: {
    url: () => secretsManager.get('DATABASE_URL')
  },

  // External services (loaded from secrets)
  aws: {
    accessKeyId: () => secretsManager.get('AWS_ACCESS_KEY_ID'),
    secretAccessKey: () => secretsManager.get('AWS_SECRET_ACCESS_KEY'),
    region: process.env.AWS_REGION || 'us-east-1'
  },

  stripe: {
    secretKey: () => secretsManager.get('STRIPE_SECRET_KEY'),
    publishableKey: process.env.STRIPE_PUBLISHABLE_KEY
  },

  // Feature flags
  features: {
    enableAuth: process.env.ENABLE_AUTH !== 'false',
    enableLogging: process.env.ENABLE_LOGGING !== 'false'
  }
};

// Initialize configuration
async function initializeConfig() {
  try {
    await secretsManager.initialize();
    console.log('Configuration initialized successfully');

    // Validate production configuration
    if (config.env === 'production') {
      validateProductionConfig();
    }

    return config;
  } catch (error) {
    console.error('Failed to initialize configuration:', error.message);
    throw error;
  }
}

function validateProductionConfig() {
  const requiredInProduction = [
    'SESSION_SECRET',
    'JWT_SECRET',
    'DATABASE_URL'
  ];

  const missing = [];
  for (const key of requiredInProduction) {
    if (!secretsManager.get(key)) {
      missing.push(key);
    }
  }

  if (missing.length > 0) {
    throw new Error(`Missing required configuration for production: ${missing.join(', ')}`);
  }
}

module.exports = {
  config,
  initializeConfig,
  secretsManager
};

