const crypto = require('crypto');

class RotationVerifier {
  constructor() {
    this.expectedChecksums = new Map();
  }

  // Store expected checksum for verification (not the actual secret)
  setExpectedChecksum(secretName, checksum) {
    this.expectedChecksums.set(secretName, checksum);
  }

  // Verify a secret matches expected checksum without exposing value
  verifySecret(secretName, secretValue) {
    const expectedChecksum = this.expectedChecksums.get(secretName);
    if (!expectedChecksum) {
      throw new Error(`No expected checksum set for ${secretName}`);
    }

    const actualChecksum = crypto
      .createHash('sha256')
      .update(secretValue)
