// Secure secrets management utility
// Supports multiple environments and secret managers

const { execSync } = require('child_process');

class SecretsManager {
  constructor() {
    this.secrets = {};
    this.loaded = false;
  }

  // Load secrets based on environment
  async loadSecrets() {
    if (this.loaded) return this.secrets;

    const env = process.env.NODE_ENV || 'development';

    try {
      switch (env) {
        case 'production':
          await this.loadProductionSecrets();
          break;
        case 'staging':
          await this.loadStagingSecrets();
          break;
        default:
          await this.loadDevelopmentSecrets();
      }

      this.loaded = true;
      console.log(`Secrets loaded for ${env} environment`);
      return this.secrets;
    } catch (error) {
      console.error('Failed to load secrets:', error.message);
      throw error;
    }
  }

  // Production: Use AWS Secrets Manager or similar
  async loadProductionSecrets() {
    try {
      // Option 1: AWS Secrets Manager
      if (process.env.AWS_SECRETS_MANAGER_SECRET_ID) {
        this.secrets = await this.loadFromAwsSecretsManager();
        return;
      }

      // Option 2: Environment variables (fallback)
      this.loadFromEnvironment();

    } catch (error) {
      console.error('Production secrets loading failed:', error.message);
      throw error;
    }
  }

  // Staging: Similar to production but with different config
  async loadStagingSecrets() {
    this.loadFromEnvironment(); // Use env vars for staging
  }

  // Development: Use .env file with validation
  async loadDevelopmentSecrets() {
    require('dotenv').config(); // Load .env file
    this.loadFromEnvironment();

    // Validate required development secrets
    this.validateSecrets([
      'API_TOKEN',
      'DATABASE_URL'
    ]);
  }

  // Load from AWS Secrets Manager
  async loadFromAwsSecretsManager() {
    try {
      // This would be implemented with AWS SDK
      // For now, return environment variables as fallback
      console.log('AWS Secrets Manager integration would be implemented here');
      return this.loadFromEnvironment();
    } catch (error) {
      console.error('AWS Secrets Manager failed:', error.message);
      throw error;
    }
  }

  // Load from environment variables
  loadFromEnvironment() {
    const requiredSecrets = [
      'API_TOKEN',
      'NODE_ENV',
      'PORT'
    ];

    const optionalSecrets = [
      'DATABASE_URL',
      'AWS_ACCESS_KEY_ID',
      'AWS_SECRET_ACCESS_KEY',
      'STRIPE_SECRET_KEY',
      'ANTHROPIC_API_KEY',
      'LOGFIRE_TOKEN'
    ];

    // Load all secrets
    const allSecrets = [...requiredSecrets, ...optionalSecrets];

    allSecrets.forEach(key => {
      if (process.env[key]) {
        this.secrets[key] = process.env[key];
      }
    });

    return this.secrets;
  }

  // Validate that required secrets are present
  validateSecrets(requiredKeys) {
    const missing = requiredKeys.filter(key => !this.secrets[key]);

    if (missing.length > 0) {
      throw new Error(`Missing required secrets: ${missing.join(', ')}`);
    }
  }

  // Get a secret
  get(key) {
    if (!this.loaded) {
      throw new Error('Secrets not loaded. Call loadSecrets() first.');
    }

    const value = this.secrets[key];
    if (!value && process.env.NODE_ENV === 'production') {
      throw new Error(`Secret ${key} not found`);
    }

    return value;
  }

  // Get all secrets (for debugging, should be used carefully)
  getAll() {
    if (!this.loaded) {
      throw new Error('Secrets not loaded. Call loadSecrets() first.');
    }

    return { ...this.secrets }; // Return copy
  }
}

// Singleton instance
const secretsManager = new SecretsManager();

module.exports = secretsManager;

// Application configuration based on environment
const secretsManager = require('./secrets');

const config = {
  // Load configuration
  async load() {
    await secretsManager.loadSecrets();

    return {
      // Server configuration
      server: {
        port: secretsManager.get('PORT') || 3000,
        env: secretsManager.get('NODE_ENV') || 'development',
      },

      // Security configuration
      security: {
        apiToken: secretsManager.get('API_TOKEN'),
        rateLimit: {
          windowMs: 15 * 60 * 1000, // 15 minutes
          max: secretsManager.get('NODE_ENV') === 'production' ? 50 : 100,
        },
      },

      // Database configuration
      database: {
        url: secretsManager.get('DATABASE_URL'),
      },

      // External services
      services: {
        aws: {
          accessKeyId: secretsManager.get('AWS_ACCESS_KEY_ID'),
          secretAccessKey: secretsManager.get('AWS_SECRET_ACCESS_KEY'),
        },
        stripe: {
          secretKey: secretsManager.get('STRIPE_SECRET_KEY'),
        },
        anthropic: {
          apiKey: secretsManager.get('ANTHROPIC_API_KEY'),
        },
        logfire: {
          token: secretsManager.get('LOGFIRE_TOKEN'),
        },
      },

      // Feature flags
      features: {
        useAwsSecretsManager: !!secretsManager.get('AWS_SECRETS_MANAGER_SECRET_ID'),
        enableStripe: !!secretsManager.get('STRIPE_SECRET_KEY'),
        enableLogging: !!secretsManager.get('LOGFIRE_TOKEN'),
      }
    };
  },

  // Helper to check if running in production
  isProduction() {
    return secretsManager.get('NODE_ENV') === 'production';
  },

  // Helper to check if running in development
  isDevelopment() {
    return secretsManager.get('NODE_ENV') === 'development';
  }
};

module.exports = config;

