#!/usr/bin/env node
/**
 * Security Cleanup Script
 * Handles sensitive files and environment configuration
 */

const fs = require('fs');
const path = require('path');

class SecurityCleanup {
  constructor() {
    this.sensitiveFiles = [
      '.env.test',
      '.env.local',
      'secrets.json',
      'config/credentials.json'
    ];

    this.sensitivePatterns = [
      /.*\.key$/,
      /.*\.pem$/,
      /.*_secret$/,
      /.*_token$/,
      /.*password.*/
    ];
  }

  /**
   * Check for sensitive files that shouldn't be in the repository
   */
  checkSensitiveFiles() {
    const found = [];

    this.sensitiveFiles.forEach(file => {
      if (fs.existsSync(file)) {
        found.push(file);
      }
    });

    // Check for pattern matches
    const allFiles = this.getAllFiles('.');
    allFiles.forEach(file => {
      this.sensitivePatterns.forEach(pattern => {
        if (pattern.test(file)) {
          found.push(file);
        }
      });
    });

    return found;
  }

  /**
   * Get all files in directory recursively
   */
  getAllFiles(dir, files = []) {
    const items = fs.readdirSync(dir);

    items.forEach(item => {
      const fullPath = path.join(dir, item);
      const stat = fs.statSync(fullPath);

      if (stat.isDirectory()) {
        this.getAllFiles(fullPath, files);
      } else {
        files.push(fullPath);
      }
    });

    return files;
  }

  /**
   * Secure a sensitive file by moving it to a safe location
   */
  secureFile(filePath, targetDir = './secure-backup') {
    if (!fs.existsSync(filePath)) {
      return { success: false, message: 'File not found' };
    }

    try {
      // Create backup directory if it doesn't exist
      if (!fs.existsSync(targetDir)) {
        fs.mkdirSync(targetDir, { recursive: true });
      }

      const fileName = path.basename(filePath);
      const targetPath = path.join(targetDir, fileName);

      // Move the file
      fs.renameSync(filePath, targetPath);

      // Set restrictive permissions
      fs.chmodSync(targetPath, 0o600); // Read/write for owner only

      return { 
        success: true, 
        message: `File secured: ${filePath} → ${targetPath}`,
        originalPath: filePath,
        securedPath: targetPath
      };
    } catch (error) {
      return { 
        success: false, 
        message: `Failed to secure file: ${error.message}`,
        error: error
      };
    }
  }

  /**
   * Validate .gitignore contains necessary patterns
   */
  validateGitignore() {
    const gitignorePath = '.gitignore';
    if (!fs.existsSync(gitignorePath)) {
      return { valid: false, missing: ['No .gitignore file found'] };
    }

    const content = fs.readFileSync(gitignorePath, 'utf8');
    const requiredPatterns = [
      '.env',
      '.env.*',
      'node_modules',
      '*.log',
      'dist',
      'build'
    ];

    const missing = requiredPatterns.filter(pattern => 
      !content.includes(pattern)
    );

    return {
      valid: missing.length === 0,
      missing: missing.length > 0 ? missing : undefined
    };
  }

  /**
   * Run comprehensive security check
   */
  async runSecurityCheck() {
    console.log('🔍 Running security check...\n');

    // Check for sensitive files
    const sensitiveFiles = this.checkSensitiveFiles();
    if (sensitiveFiles.length > 0) {
      console.log('⚠️  Sensitive files found:');
      sensitiveFiles.forEach(file => {
        console.log(`   - ${file}`);
      });
      console.log('');
    } else {
      console.log('✅ No sensitive files found\n');
    }

    // Validate .gitignore
    const gitignoreCheck = this.validateGitignore();
    if (!gitignoreCheck.valid) {
      console.log('⚠️  .gitignore validation failed:');
      gitignoreCheck.missing.forEach(pattern => {
        console.log(`   - Missing pattern: ${pattern}`);
      });
      console.log('');
    } else {
      console.log('✅ .gitignore validation passed\n');
    }

    // Check node_modules for known vulnerabilities
    console.log('📦 Checking for known vulnerabilities...');
    try {
      const { execSync } = require('child_process');
      execSync('npm audit --audit-level moderate', { stdio: 'inherit' });
      console.log('✅ npm audit completed\n');
    } catch (error) {
      console.log('⚠️  npm audit found vulnerabilities\n');
    }

    return {
      sensitiveFiles,
      gitignoreValid: gitignoreCheck.valid,
      hasVulnerabilities: true // Simplified for this example
    };
  }
}

// Command line interface
if (require.main === module) {
  const cleanup = new SecurityCleanup();

  const command = process.argv[2];

  switch (command) {
    case 'check':
      cleanup.runSecurityCheck();
      break;

    case 'secure':
      const fileToSecure = process.argv[3] || '.env.test';
      const result = cleanup.secureFile(fileToSecure);
      console.log(result.message);
      break;

    case 'validate-gitignore':
      const check = cleanup.validateGitignore();
      console.log('Gitignore validation:', check.valid ? 'PASS' : 'FAIL');
      if (!check.valid) {
        console.log('Missing patterns:', check.missing);
      }
      break;

    default:
      console.log('Security Cleanup Script');
      console.log('Usage:');
      console.log('  node cleanup-secrets.js check          - Run security check');
      console.log('  node cleanup-secrets.js secure [file]  - Secure a sensitive file');
      console.log('  node cleanup-secrets.js validate-gitignore - Validate .gitignore');
  }
}

module.exports = SecurityCleanup;

