// Environment configuration with secure defaults
// For production, use environment variables or secrets manager

const requiredEnvVars = [
  'NODE_ENV',
  'PORT',
  'JWT_SECRET'
];

const validateEnvironment = () => {
  const missing = requiredEnvVars.filter(varName => 
    !process.env[varName] || process.env[varName].trim() === ''
  );

  if (missing.length > 0) {
    throw new Error(`Missing required environment variables: ${missing.join(', ')}`);
  }

  // Validate JWT secret strength in production
  if (process.env.NODE_ENV === 'production' && process.env.JWT_SECRET) {
    if (process.env.JWT_SECRET.length < 32) {
      throw new Error('JWT_SECRET must be at least 32 characters long in production');
    }
  }
};

// Secret management abstraction
const getSecret = (key, defaultValue = null) => {
  // In production, this would interface with AWS Secrets Manager, HashiCorp Vault, etc.
  const value = process.env[key] || defaultValue;

  if (!value && process.env.NODE_ENV === 'production') {
    throw new Error(`Required secret '${key}' not found`);
  }

  return value;
};

module.exports = {
