const { SecretsManager } = require('@aws-sdk/client-secrets-manager');

class SecretsManager {
  constructor() {
    this.secrets = {};
    this.initialized = false;
  }

  async initialize() {
    if (process.env.USE_AWS_SECRETS_MANAGER === 'true') {
      await this.loadFromAWS();
    } else if (process.env.USE_VAULT === 'true') {
      await this.loadFromVault();
    } else {
      // Fallback to environment variables
      this.secrets = process.env;
    }
    this.initialized = true;
  }

  async loadFromAWS() {
    const client = new SecretsManager({
      region: process.env.AWS_REGION
    });

    const secretData = await client.getSecretValue({
      SecretId: process.env.SECRETS_ARN
    }).promise();

    this.secrets = JSON.parse(secretData.SecretString);
  }

  get(key) {
    if (!this.initialized) {
      throw new Error('Secrets manager not initialized');
    }
    return this.secrets[key];
  }
}

// Initialize secrets
const secrets = new SecretsManager();
await secrets.initialize();

const app = express();
const PORT = secrets.get('PORT') || 3000;

// Use secrets throughout the application
